(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.NetView=api;})(globalThis,function(){
const pos={K:[60,160],A:[180,160],L:[180,50],B:[320,65],C:[320,250],D:[460,160],W:[590,160]},names={K:'Client',A:'Weiterleitung',B:'Weiterleitung',C:'Weiterleitung',D:'Weiterleitung',L:'lokaler Dienst',W:'ferner Dienst'};
function svg(disabled=[],at=''){const edges=['K-A','A-L','A-B','A-C','B-C','B-D','C-D','D-W'];return '<svg class="net-graph" viewBox="0 0 660 300" role="img" aria-label="Netzmodell. Die Verbindungen und ihr Zustand stehen auch als Text unter der Grafik.">'+edges.map(e=>{const [a,b]=e.split('-'),off=disabled.includes(e),x=(pos[a][0]+pos[b][0])/2,y=(pos[a][1]+pos[b][1])/2;return '<line x1="'+pos[a][0]+'" y1="'+pos[a][1]+'" x2="'+pos[b][0]+'" y2="'+pos[b][1]+'" stroke="'+(off?'#92351d':'#60786a')+'" stroke-width="3"'+(off?' stroke-dasharray="6 5"':'')+'/>'+(off?'<text x="'+x+'" y="'+(y-5)+'" class="net-cut">×</text>':'');}).join('')+Object.entries(pos).map(([n,[x,y]])=>'<circle cx="'+x+'" cy="'+y+'" r="21" fill="'+(n===at?'#ffd478':'#fff')+'" stroke="#24543e" stroke-width="3"/><text x="'+x+'" y="'+(y+6)+'" text-anchor="middle" font-weight="700">'+n+'</text><text x="'+x+'" y="'+(y+40)+'" text-anchor="middle" font-size="16">'+names[n]+'</text>').join('')+'</svg>';}
return {svg};});
